import glob
import os
import re
import subprocess

from typing import Union

from pathlib import Path
from robot.libraries.BuiltIn import BuiltIn

from taf.rfrl.csv4all.resources.utilities.utilities import test_logger


class Nescrotta:
    def __init__(self, feature_release: str, source_release: str, feature: str, config_type: str,
                 nescrotta_path: str = "/mnt/NESCRotta", tool: str = "WebEM", ca: str = "VRF_WRO3",
                 team: str = "VRF_WRO3_T03"):
        self.feature_release = feature_release
        self.source_release = source_release
        self.feature = feature
        self.config_type = config_type
        self.nescrotta_path = nescrotta_path
        self.tool = tool
        self.feature_path = self.get_feature_path(ca, team)

    def umount_nescrotta(self):
        test_logger("Unmunting Nescrotta")
        if subprocess.getoutput(f"df -ah | grep {self.nescrotta_path}"):
            subprocess.Popen(f"sudo umount -f {self.nescrotta_path}", shell=True)

    def mount_nescrotta(self):
        test_logger("Mounting Nescrotta")
        if not os.path.ismount(self.nescrotta_path):
            nescrotta_uuf = "/home/ute/MN/UTE/gears/gears.wroclaw.uuf/resources/nescrotta"
            credentials = nescrotta_uuf if Path(nescrotta_uuf).exists() else \
                BuiltIn().get_variable_value("${NESCROTTA_CREDENTIAL_PATH}")
            if credentials:
                cmd = f"sudo mkdir {self.nescrotta_path}; sudo mount -t cifs -o " \
                      f"credentials={credentials}," \
                      f"rw,nounix,file_mode=0777,dir_mode=0777,uid=ute,gid=ute,vers=3.0 " \
                      f"//nescrotta.nesc.nokia.net/rotta {self.nescrotta_path}"
                test_logger(cmd, "DEBUG")
                process = subprocess.Popen(cmd, shell=True, stdout=subprocess.DEVNULL, stderr=subprocess.STDOUT)
                output, error = process.communicate()
                test_logger(error, console=False)
            else:
                test_logger("Mounting Nescrotta not possible", "WARN")

    def send_snapshot_to_nescrotta(self, logs_dir: str, operation: str) -> None:
        path = self.get_nescrotta_path(operation)
        if path:
            test_logger(f"Path on nescrotta: {path}", console=False)
            self.copy_logs_to_nescrotta(logs_dir, path)

    def get_nescrotta_path(self, operation: str) -> Union[str, None]:
        operation = 'Upgrade' if operation.lower() == 'update' else operation
        operation = operation.capitalize()
        if not self.feature or not self.config_type:
            return None
        if operation == 'Upgrade':
            from_release = self.source_release
            to_release = self.feature_release
        else:
            from_release = self.feature_release
            to_release = self.source_release

        if os.path.exists(os.path.join(self.feature_path, self.config_type)):
            config_directory = os.path.join(self.feature_path, self.config_type)
        else:
            test_logger(f"Path doesnt exists on nescrotta: {self.feature_path}/{self.config_type}", console=False)
            return
        directories = os.listdir(config_directory)
        nescrotta_snapshot_dir = f"UUF__SWM__{self.feature}_{operation}_of_SBTS_from_release_{from_release}_" \
                                 f"to_release_{to_release}_via_{self.tool}"
        if not directories:
            os.makedirs(os.path.join(config_directory, nescrotta_snapshot_dir), exist_ok=True)
            return os.path.join(config_directory, nescrotta_snapshot_dir)
        else:
            for directory in directories:
                if re.match(fr"UUF.*{self.feature}.*{operation}.*{from_release}.*{to_release}.*{self.tool}".lower(),
                            directory.lower()):
                    return os.path.join(config_directory, directory)
                else:
                    os.makedirs(os.path.join(config_directory, nescrotta_snapshot_dir), exist_ok=True)
                    return os.path.join(config_directory, nescrotta_snapshot_dir)

    @staticmethod
    def copy_logs_to_nescrotta(log_path: str, path: str) -> None:
        if path and "zip" not in str(os.listdir(path)):
            snapshot_file = glob.glob(f"{log_path}/Snapshot*.zip")
            if snapshot_file:
                command_to_copy = f"cp '{snapshot_file[0]}' '{path}'"
                test_logger(command_to_copy, "DEBUG")
                process = subprocess.Popen(command_to_copy, shell=True, universal_newlines=True,
                                           stdout=subprocess.PIPE, stderr=subprocess.PIPE)
                test_logger('Uploading snapshot to NESCRota')
                output, error = process.communicate()
                test_logger(f"Output from error: {error}", "DEBUG")
                test_logger(f"Logs{' not' if error else ''} uploaded to nescrotta")
            else:
                test_logger(f"Couldnt get snapshot under: {log_path}")
        elif path and "zip" in str(os.listdir(path)):
            test_logger("Snapshot already exists on nescrotta")
        else:
            test_logger("Couldnt get destination directory on nescrotta")

    def get_feature_path(self, ca: str, team: str):
        return f"{self.nescrotta_path}/MN_RAN/RAN_VRF/{self.feature_release}/New_Features/{ca}/" \
               f"{team}/{self.feature}/"
